import tkinter as tk
import os
import re
import yaml
import webbrowser
from tkinter import ttk

from pathlib import Path
from PIL import Image, ImageTk

from ..widgets.notebook_tabs import NotebookTabs
from ..widgets.header_section import HeaderWidgetsSection

from ..utils.get_bbmod_smod_depend_on_profile import get_bbmod_smod_depend_on_profile
from ..utils.logger import logger


class View(tk.Frame):

    def __init__(self, parent, model):
        super().__init__(parent, name='view_frame')
        self.graphics_path = Path(os.path.abspath(__file__)).parents[1] / "graphics"
        self.config(bg="white")
        self._create_header()
        self.model = model
        self.bbmods_smods_info = self.model.bbmods_smods_info
        self.rmods_info = self.model.rmods_info
        self.header_widgets_section = HeaderWidgetsSection(self, model)
        self.header_widgets_section.grid(row=1, sticky="ew")

        self.cus_ports = None
        self.current_topology = None

        self.notebook_tabs = NotebookTabs(self, model, parent)
        self.notebook_tabs.grid(row=2, column=0, sticky="ew")
        self.header_widgets_section.bind(
            '<<EnableCustomCButtonChanged>>', lambda ev: self.lock_unlock_bbmod_smod_section()
        )
        self.header_widgets_section.children['select_profile_combobox'].bind(
            '<<ComboboxSelected>>', lambda ev: self.set_widgets_depend_on_chosen_profile(ev)
        )
        self.bind_all('<<NewTypeSmodSelected>>',
                      lambda ev: self.lock_and_reset_bbmod_section_after_new_smod_selection(ev))
        self.bind_all('<<UnlockBbmodSelected>>', lambda ev: self.unlock_bbmod_section_after_new_smod_selection(ev))
        self.bind_all('<<RequireValidation>>', lambda ev: self.header_widgets_section.lock_generate_config(ev))
        self.bind_all('<<ValidateConfig>>', lambda ev: self.validate_configuration())
        self.lock_whole_acg_view()

    def lock_and_reset_bbmod_section_after_new_smod_selection(self, event):
        def get_children(widget, state):
            if (isinstance(widget, tk.Frame) or isinstance(widget, ttk.Frame)
                    or isinstance(widget, tk.Canvas) or isinstance(widget, tk.LabelFrame)):
                for children in widget.winfo_children():
                    get_children(children, state)
            elif hasattr(widget, 'state'):
                try:
                    if state:
                        widget.config(state="disabled")
                    else:
                        widget.config(state="normal")
                except tk.TclError:
                    pass

                return False
            else:
                return False

        tab = event.widget
        bbmods_frame = tab.children['bbmod_frame_section']
        get_children(bbmods_frame, 'disabled')

    def get_selected_profile(self):
        return self.current_topology

    def unlock_bbmod_section_after_new_smod_selection(self, event):
        def get_children(widget, state):
            if (isinstance(widget, tk.Frame) or isinstance(widget, ttk.Frame)
                    or isinstance(widget, tk.Canvas) or isinstance(widget, tk.LabelFrame)):
                for children in widget.winfo_children():
                    get_children(children, state)
            elif hasattr(widget, 'state'):
                try:
                    if state:
                        widget.config(state="disabled")
                    else:
                        widget.config(state="normal")
                except tk.TclError:
                    pass

                return False
            else:
                return False

        tab = event.widget
        bbmods_frame = tab.children['bbmod_frame_section']
        get_children(bbmods_frame, False)

    def get_children(self, widget, state):
        if any(
                (isinstance(widget, tk.Frame), isinstance(widget, ttk.Frame),
                 isinstance(widget, tk.Canvas), isinstance(widget, tk.LabelFrame))
        ):
            for children in widget.winfo_children():
                self.get_children(children, state)
        elif hasattr(widget, 'state'):
            try:
                widget.config(state=state)
            except tk.TclError:
                pass

    def lock_whole_acg_view(self):
        for tab in self.notebook_tabs.children.values():
            self.get_children(tab, 'disabled')

    def set_profile(self, profile):
        enbs_dict = get_bbmod_smod_depend_on_profile(profile, self.bbmods_smods_info, self.rmods_info)

        self.notebook_tabs.reset_tab_view()

        for enb in enbs_dict.keys():
            self.notebook_tabs.add_new_enb_tab()

        self._set_cus_ports_for_profile(profile.upper())
        cus_ports = self.cus_ports  # TODO
        self.model.cus_ports = cus_ports
        # cus_ports = self.model.cus_ports[profile.upper()]
        tab_index = []
        for enb in enbs_dict.keys():
            for i, tab in enumerate(self.notebook_tabs.tabs()):
                if "viewacg" in tab and i not in tab_index:
                    tab_index.append(i)
                    name = tab.split('.')[-1]

                    smods_frame_section = self.notebook_tabs.children[name].children['smod_frame_section']
                    bbmods_frame_section = self.notebook_tabs.children[name].children['bbmod_frame_section']
                    rmods_frame_section = self.notebook_tabs.children[name].children['rmods_frame_section']
                    cells_frame_section = self.notebook_tabs.children[name].children['cell_frame_section']

                    for smod_name in enbs_dict[enb]['smods'].values():
                        smods_frame_section._set_smod(smod_name=smod_name)

                    if enbs_dict[enb]['bbmods']:
                        sorted_bbmods = dict(sorted(enbs_dict[enb]['bbmods'].items(), key=lambda item: int(item[0])))

                        for bbmod_name in sorted_bbmods.values():
                            bbmods_frame_section._add_bbmod(bbmod_name=bbmod_name)

                        for rmod in enbs_dict[enb]['rmods'].values():
                            ports = cus_ports[enb.upper()][f'BBMOD-{rmod["bbmod"]}'].keys()
                            rmod_id = rmod['port']
                            port = [port for port in ports if re.search(rf'RF{rmod_id} .*', port)][0]
                            rmods_frame_section._add_rmod(rmod_name=rmod['type'],
                                                          connections=[(f"{enbs_dict[enb]['bbmods'][rmod['bbmod']]} "
                                                                        f"(BBMOD-{rmod['bbmod']})", port)])
                    else:
                        self.notebook_tabs.children[name].fetch_bbmods_func = self.notebook_tabs.children[
                            name].fetch_smods

                        for rmod in enbs_dict[enb]['rmods'].values():
                            ports = cus_ports[enb.upper()][f'SMOD-{rmod["smod"]}'].keys()
                            rmod_id = rmod['port']
                            port = [port for port in ports if re.search(rf'RF{rmod_id} .*', port)][0]
                            rmods_frame_section._add_rmod(rmod_name=rmod['type'],
                                                          connections=[(f"{enbs_dict[enb]['smods'][rmod['smod']]} "
                                                                        f"(SMOD-{rmod['smod']})", port)])

                    for cell_id, cell in enbs_dict[enb]['cells'].items():
                        earfcn_type = "earfcn_dl" if cell.get("earfcn_dl") else "earfcn"
                        cell_technology = "FDD" if earfcn_type == "earfcn_dl" else "TDD"
                        mplane_only = cell['mplane_only']
                        connections = cell['connections']['radio']
                        connected_radio_list = list(connections.keys())
                        cells_frame_section._add_cell(connections=[
                            (
                                f"{enbs_dict[enb]['rmods'][connected_radio_list[0]]['type']} (RMOD-{connected_radio_list[0]})",
                                f"{connections[connected_radio_list[0]]['1']}",
                                f"{connections[connected_radio_list[0]]['2']}",
                                f"{connections[connected_radio_list[0]]['3']}",
                                f"{connections[connected_radio_list[0]]['4']}",
                                f"{connections[connected_radio_list[0]]['5']}",
                                f"{connections[connected_radio_list[0]]['6']}",
                                f"{connections[connected_radio_list[0]]['7']}",
                                f"{connections[connected_radio_list[0]]['8']}"
                            )], ch_bw=cell['ch_bw'], earfcn=cell[earfcn_type],
                            cell_technology=cell_technology, mplane_only=mplane_only)
                        if len(connections) > 1:
                            for index, radio_id in enumerate(connections.keys()):
                                if index != 0:
                                    cells_frame_section.children['cells_canvas'].children['cells_frame'] \
                                        .children[f'cell_{cell_id}']._add_connection_frame(connection=(
                                            f"{enbs_dict[enb]['rmods'][connected_radio_list[index]]['type']} (RMOD-{connected_radio_list[index]})",
                                            f"{connections[connected_radio_list[index]]['1']}",
                                            f"{connections[connected_radio_list[index]]['2']}",
                                            f"{connections[connected_radio_list[index]]['3']}",
                                            f"{connections[connected_radio_list[index]]['4']}",
                                            f"{connections[connected_radio_list[index]]['5']}",
                                            f"{connections[connected_radio_list[index]]['6']}",
                                            f"{connections[connected_radio_list[index]]['7']}",
                                            f"{connections[connected_radio_list[index]]['8']}"))
                    self.notebook_tabs.children[name].update_view_config(profile=profile.upper(),
                                                                         enb_id=re.search(r'\d+', enb).group(0))
                    bbmods_frame = self.notebook_tabs.children[name].children['bbmod_frame_section']
                    smods_frame = self.notebook_tabs.children[name].children['smod_frame_section']
                    self.lock_after_topology_selected(bbmods_frame)
                    self.lock_after_topology_selected(smods_frame)
                    self.header_widgets_section.message.delete(0.0, tk.END)
                    break

    def set_widgets_depend_on_chosen_profile(self, event):
        chosen_tl_label = self.header_widgets_section.children['select_profile_combobox'].get()
        self.set_profile(chosen_tl_label)

        if not self.current_topology:
            self.header_widgets_section.enable_custom_config_checkbutton_after_first_topology_is_selected()

        self.current_topology = chosen_tl_label
        # clear validation log
        self.header_widgets_section.message.delete(0.0, tk.END)
        # when user was in custom mode and chagned topologu -> disable custom config
        self.header_widgets_section.disable_custom_config_after_topology_is_selected()
        self.notebook_tabs.enable_custom_config = False

    def lock_after_topology_selected(self, frame):
        def get_children(widget, state):
            if (isinstance(widget, tk.Frame) or isinstance(widget, ttk.Frame)
                    or isinstance(widget, tk.Canvas) or isinstance(widget, tk.LabelFrame)):
                for children in widget.winfo_children():
                    get_children(children, state)
            elif hasattr(widget, 'state'):
                try:
                    if state:
                        widget.config(state="disabled")
                    else:
                        widget.config(state="normal")
                except tk.TclError:
                    pass

                return False
            else:
                return False

        get_children(frame, 'disabled')

    # flake8: noqa: C901
    def lock_unlock_bbmod_smod_section(self, called_from_event=True):
        def get_children(widget, state):
            if (isinstance(widget, tk.Frame) or isinstance(widget, ttk.Frame)
                    or isinstance(widget, tk.Canvas) or isinstance(widget, tk.LabelFrame)):
                for children in widget.winfo_children():
                    if "bbmod_frame_section" in str(children) or "smod_frame_section" in str(children):
                        get_children(children, state)
                    else:
                        get_children(children,
                                     True)  # optimize in the future to enable cells/rmods only after the first profile selection
            elif hasattr(widget, 'state') and 'antl_' not in str(widget):
                try:
                    if not state:
                        widget.config(state="disabled")
                    else:
                        widget.config(state="normal")
                except tk.TclError:
                    pass

                return False
            else:
                return False

        enabled = self.header_widgets_section.generate_profile_setup_var.get()
        self._set_profile_to_current_topo(enabled, called_from_event)

        i = 1
        for tab in self.notebook_tabs.children:
            if 'viewacg' not in tab:
                continue
            acg = self.notebook_tabs.children[tab]
            acg.children['rmods_frame_section'].custom_enabled = bool(enabled)
            acg.children['rmods_frame_section'].hide_grid_cus_port_entry_box()
            if not enabled:
                acg.children['rmods_frame_section'].selected_topology = self.current_topology
                acg.children['rmods_frame_section'].enb_id = i
            else:
                acg.children['rmods_frame_section'].set_links_without_cus()
                acg.update_view_config()
            get_children(acg, enabled)
            i += 1

        self.notebook_tabs.enable_custom_config = bool(self.header_widgets_section.generate_profile_setup_var.get())

    def _set_profile_to_current_topo(self, enabled, called_from_event):
        if called_from_event and not enabled:
            # from Enabled to Disabled ==> reset topology to selected profile
            self.set_profile(self.current_topology)

    def _create_header(self):
        graphic_src_path = Path(os.path.abspath(__file__)).parents[1] / "graphics"
        logo_pic = Image.open(graphic_src_path / "Nokia_logo_white.png").resize((118, 30))
        self.logo = ImageTk.PhotoImage(logo_pic, master=self)  # must be definied in class attribute, otherwise it will disappear
        cus_logo_pic = Image.open(graphic_src_path / "CUS_logo.png").resize((85, 44))
        self.cus_logo = ImageTk.PhotoImage(cus_logo_pic, master=self)
        help_pic = Image.open(graphic_src_path / "Help.png").resize((30, 30))
        self.help_pic = ImageTk.PhotoImage(help_pic, master=self)

        header_frame = ttk.Frame(self)
        header_frame.grid(row=0, sticky="ew")

        logo = ttk.Label(header_frame, image=self.logo, width=15, background="#00A0B5", padding=(20, 0, 290, 0),
                         anchor=tk.W, name="logo")

        cus_logo = ttk.Label(header_frame, image=self.cus_logo, width=15, background="#00A0B5",
                             anchor=tk.W, name="cus_logo")

        app_name = tk.Label(
            header_frame, text="ACG App", bg="#00A0B5", fg="white", anchor=tk.E,
            font=('Helvetica', 23, 'bold'), padx=15, name="app_name")

        def open_webpage():
            webbrowser.open("https://confluence.ext.net.nokia.com/display/CUStool/CUS+AutoConfig+App")

        button = tk.Button(header_frame, text="Show Link", command=open_webpage, image=self.help_pic,
                           borderwidth=0, bg="#00A0B5", highlightthickness=0)

        logo.pack(ipadx=10, ipady=10, side="left", fill=tk.BOTH, expand=True)
        cus_logo.pack(ipadx=10, ipady=10, side="left", fill=tk.BOTH, expand=True)
        button.pack(side="right", fill=tk.BOTH, ipadx=5)
        app_name.pack(ipady=0, fill=tk.BOTH, side="right", expand=True)

    def get_configuration(self):
        configuration = {}
        configuration['selected_profile'] = self.header_widgets_section.children['select_profile_combobox'].get()
        configuration['selected_build'] = self.header_widgets_section.children['select_enb_build_combobox'].get()
        if not configuration['selected_profile']:
            raise Exception("Please select TL Profile first")

        for i, tab in enumerate(self.notebook_tabs.tabs()[2:-1]):
            name = tab.split('.')[-1]
            configuration[i + 1] = self.notebook_tabs.children[name].get_configuration()

        return configuration

    def validate_configuration(self):
        log_lines = []
        log_lines += self.header_widgets_section.get_log_lines()

        if self.current_topology is not None:
            for i, tab in enumerate(self.notebook_tabs.tabs()[2:-1]):
                name = tab.split('.')[-1]
                for log in self.notebook_tabs.children[name].get_validation_log(self.get_selected_profile()):
                    if not log:
                        continue
                    for line in log:
                        log_lines.append(f"[ENB-{i + 1}] {line}")

        if log_lines:
            msg = '\n'.join(log_lines)
            self.header_widgets_section.message.delete(0.0, tk.END)
            self.header_widgets_section.message.insert(0.0, msg)
            logger.info(f"Validation unsuccessful with result {msg}")
        else:
            self.header_widgets_section.message.delete(0.0, tk.END)
            self.header_widgets_section.message.insert(0.0, 'Validation Successful!')
            logger.info("Validation successful")
            self.header_widgets_section.unlock_generate_config()

    def get_output_path(self):
        return self.header_widgets_section.get_output_path()

    def _set_cus_ports_for_profile(self, profile):
        profile_path = Path(os.path.abspath(__file__)).parents[2] / "config" / "profiles" / profile / "hw.yaml"
        hw_yaml = self._open_yaml_file(profile_path)
        rf_links = hw_yaml['rf_links']

        cus_ports = {}

        for enb_key, bbmod_or_smod in rf_links.items():
            cus_ports[enb_key.upper()] = {}
            for bbmod_or_smod_key, ports in bbmod_or_smod.items():
                new_key = bbmod_or_smod_key.replace('_', '-').upper()
                cus_ports[enb_key.upper()][new_key] = {}
                for port_number, definition in ports.items():
                    key = f'RF{port_number.removeprefix("port")} (CUS{definition.split(".")[0]})'
                    value = f'{".".join(definition.split(".")[1:])}'
                    cus_ports[enb_key.upper()][new_key][key] = value

        self.cus_ports = cus_ports

    @staticmethod
    def _open_yaml_file(path):
        with open(path) as f:
            yaml_file = yaml.load(f, Loader=yaml.BaseLoader)
        return yaml_file
